// Studio redesign (docs/design/studio/BRIEF.md, motion contract): the spring easings in styles.css are generated by
// src/motion/spring.ts (ported from Motion). This fails if a token is edited by hand or the generator changes without
// the stylesheet, and pins the property the faceplate depends on: the "settle" spring never passes its target, so the
// thermal scale is never drawn beyond the reading it shows.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { SPRINGS, springEasing, springToken } from '../src/motion/spring.js';

const css = readFileSync(join(import.meta.dirname, '..', 'src', 'styles.css'), 'utf8');
/** A custom property's declared value with formatting whitespace collapsed (Prettier wraps long `linear()` lists). */
const declared = (prop: string): string | undefined =>
  new RegExp(`${prop}:\\s*([^;]*);`)
    .exec(css)?.[1]
    ?.replace(/\s+/g, ' ')
    .replace(/\( /g, '(')
    .replace(/ \)/g, ')')
    .trim();

describe('T-052 studio spring easing tokens', () => {
  for (const name of Object.keys(SPRINGS) as (keyof typeof SPRINGS)[]) {
    it(`--ease-${name} in styles.css matches the generator`, () => {
      expect(declared(`--ease-${name}`)).toBe(springToken(name));
    });
  }

  it('settle starts at 0, ends at 1 and never overshoots', () => {
    const e = springEasing(SPRINGS.settle);
    expect(e(0)).toBe(0);
    expect(e(1)).toBe(1);
    let prev = 0;
    for (let i = 1; i <= 200; i++) {
      const v = e(i / 200);
      expect(v).toBeLessThanOrEqual(1);
      expect(v).toBeGreaterThanOrEqual(prev);
      prev = v;
    }
  });

  it('every transition that uses a spring token lasts the duration the token was sampled for', () => {
    for (const name of Object.keys(SPRINGS) as (keyof typeof SPRINGS)[])
      expect(declared(`--dur-${name}`)).toBe(`${SPRINGS[name].durationMs}ms`);
  });
});
